// Suggested questions on the Ask Amio screen (frame R30AskAmio). Learners
// tap one instead of typing (rule 1). Built only from reviewed Course
// lessons the learner already studied (their new words and titles) and
// fixed text, never generated by AI, and nothing new is saved.

export const MAX_LESSON_SUGGESTIONS = 3;

// Before the learner has studied any lesson, and about the interview: fixed,
// the same for everyone. Keys into ASK_SCREEN_LINES (src/lib/askTutor.js),
// so they are shown in the learner's language.
export const STARTER_SUGGESTIONS = ['q_branches', 'q_constitution', 'q_rights'];
export const INTERVIEW_SUGGESTIONS = ['q_how_long', 'q_dont_understand', 'q_what_happens'];

/**
 * Up to 3 questions from the learner's 2 most recent Course lessons: "What
 * does "{word}" mean?" (the lesson's first reviewed new word) and "Explain
 * "{title}" again". Each carries its answer's parts, which are reviewed
 * course content already in the translation pack: the word's meaning, or the
 * lesson's facts (askAnswers.js courseAnswer()). Only reviewed lessons.
 *
 * progress: lesson_progress rows ({ lesson_id, completed_at, last_attempt_date })
 * find: lessonId → Course lesson ((id) => findLesson(id)?.lesson, src/lib/course.js)
 */
export function lessonSuggestions(progress = [], find = () => null, max = MAX_LESSON_SUGGESTIONS) {
  const when = (p) => p.completed_at || p.last_attempt_date || p.updated_date || '';
  const recent = [...progress]
    .filter((p) => find(p.lesson_id)?.status === 'reviewed')
    .sort((a, b) => String(when(b)).localeCompare(String(when(a))));
  const seen = new Set();
  const terms = [];
  const titles = [];
  for (const p of recent) {
    if (seen.has(p.lesson_id)) continue;
    seen.add(p.lesson_id);
    if (seen.size > 2) break; // the 2 most recent lessons
    const lesson = find(p.lesson_id);
    const listen = lesson.steps?.listen || {};
    const word = (listen.newWords || []).find((w) => w.status !== 'draft' && w.word && w.meaning);
    if (word) terms.push({ id: `course_${lesson.id}_term`, question: `What does "${word.word}" mean?`, lead: `${word.word}: `, parts: [word.meaning] });
    if (lesson.title && listen.facts?.length) titles.push({ id: `course_${lesson.id}_title`, question: `Explain "${lesson.title}" again`, lead: '', parts: [...listen.facts] });
  }
  return [...terms, ...titles].slice(0, max);
}
